/* Practice content for the Patho Final GI unit: flashcards, questions, sorting games, chain builders, triage sets.
   The instructor has not published a Final exam study guide yet, so questions are NCLEX-style:
   mostly multiple choice and select all that apply (the formats on earlier Patho exams), plus a few
   Next Gen formats (selectn, matrix, cloze). Each question has diff (easy/medium/hard) and a why rationale.
   All items are new, written from the three lecture guides and transcripts. */

window.FLASHCARDS = [
  // Foundations
  ["found", "The instructor's first question for every GI disorder", "What normal function has been disrupted? Wrong direction, damaged lining, blocked passage, or lost organ function?"],
  ["found", "Four stomach defenses", "Mucus + bicarbonate, tight junctions, blood flow and repair, prostaglandins (support the others)."],
  ["found", "Parietal cells make…", "HCl and intrinsic factor (needed for B12 absorption in the terminal ileum)."],
  ["found", "Chief cells release…", "Pepsinogen, which acid converts to pepsin (digests protein)."],
  ["found", "Why does the stomach need defenses at all?", "Acid and pepsin can digest the stomach's own tissue (muscle is protein)."],
  ["found", "Stomach injury is a ___ problem", "Balance. Injury can happen when defenses weaken even if acid production is normal."],
  ["found", "What clears small, normal amounts of reflux?", "Saliva (neutralizes acid) and peristalsis (pushes contents back down)."],
  ["found", "Vomiting stomach acid causes which acid-base imbalance?", "Metabolic alkalosis (loss of HCl)."],
  ["found", "Why can Hgb look normal early in a big bleed?", "Plasma and RBCs are lost together; it drops after fluid shifts or IV fluids."],
  ["found", "Why can BUN rise in an upper GI bleed?", "Digested blood adds a nitrogen load, and kidney perfusion falls."],
  ["found", "Slow GI bleeding leads to…", "Iron deficiency anemia → less O₂ delivery → fatigue, low activity tolerance."],
  ["found", "Rapid GI bleeding leads to…", "↓Venous return → ↓stroke volume → ↓CO; tachycardia and vasoconstriction, then hypotension and shock."],
  ["found", "Visceral vs. parietal pain", "Organs (visceral) localize pain poorly; the parietal peritoneum localizes it well."],
  ["found", "The recurring worst case for anything that blocks or inflames the gut", "Perforation → peritonitis → sepsis."],
  // Upper GI
  ["upper", "GER vs. GERD", "GER = reflux itself, occasional and normal. GERD = reflux causing troublesome, recurrent symptoms or complications."],
  ["upper", "Core mechanism of GERD", "The LES barrier fails (relaxes when it should stay closed), so acid sits on an esophagus that lacks the stomach's protection."],
  ["upper", "Four contributors to GERD", "↑Abdominal pressure (pregnancy, adipose), large meals/delayed emptying, smoking and LES-lowering drugs, hiatal hernia."],
  ["upper", "Heartburn is worse after…", "Eating (fuller stomach), bending (↑abdominal pressure), lying down (loses gravity)."],
  ["upper", "GERD red flags that need more testing", "Difficulty swallowing, unexplained weight loss, signs of bleeding."],
  ["upper", "Barrett's esophagus", "Long-term reflux changes the type of cells lining the lower esophagus → ↑cancer risk (most don't get cancer)."],
  ["upper", "Do PPIs stop reflux?", "No. They don't change the LES; they lower acid so refluxed contents injure less."],
  ["upper", "Dysphagia vs. odynophagia", "Dysphagia = difficulty swallowing. Odynophagia = painful swallowing."],
  ["upper", "Five causes of esophagitis", "GERD (most common), pill esophagitis, radiation, Candida, eosinophilic esophagitis (EoE)."],
  ["upper", "How is EoE confirmed?", "Eosinophils in esophageal tissue on biopsy. A blood eosinophil count can't confirm it."],
  ["upper", "Esophageal stricture", "Dense scar from repeated injury and healing; narrows the esophagus and doesn't relax when inflammation improves."],
  ["upper", "Four causes of gastritis", "H. pylori, autoimmune (parietal cells), NSAIDs/alcohol/bile, severe physiologic stress."],
  ["upper", "How does H. pylori survive stomach acid?", "Lives in the mucus layer and makes urease, making its surroundings less acidic."],
  ["upper", "How do NSAIDs injure the stomach?", "↓Prostaglandins → less mucus, less bicarbonate, less mucosal blood flow."],
  ["upper", "Tests that detect active H. pylori", "Urea breath test or stool antigen test."],
  ["upper", "Gastritis → two kinds of anemia", "Chronic blood loss → iron deficiency. Autoimmune parietal cell loss → no intrinsic factor → B12 (pernicious) anemia."],
  ["upper", "Erosion vs. ulcer", "Depth. An ulcer goes through the muscularis mucosae; an erosion stays in the mucosa."],
  ["upper", "Two major causes of PUD", "H. pylori and NSAIDs. Smoking impairs healing. Spicy food is not a major cause."],
  ["upper", "Gastric vs. duodenal ulcer pain (classic)", "Gastric: worse after eating. Duodenal: may improve briefly with eating, then return. Not reliable for location."],
  ["upper", "Three PUD complications by depth/location", "Reaches a vessel → bleeding; full wall → perforation → peritonitis; near the outlet → obstruction → persistent vomiting."],
  ["upper", "Coffee-ground emesis means…", "Blood exposed to stomach acid: a stomach source."],
  ["upper", "Melena", "Black, tarry stool from upper GI blood broken down as it passes through the intestines."],
  ["upper", "Can bright red rectal blood come from an upper GI bleed?", "Yes, if the bleed is very rapid. Color alone doesn't establish the source."],
  ["upper", "Ulcer bleed vs. variceal bleed", "Ulcer erodes into a vessel. Varices: portal hypertension enlarges veins until they rupture."],
  ["upper", "Upper GI bleeding causes", "Peptic ulcers, erosive gastritis, esophagitis, tears from forceful vomiting, ruptured varices."],
  // Lower GI
  ["lower", "Biggest risk factor for C. diff", "Recent antibiotic use (especially broad-spectrum): kills the normal flora."],
  ["lower", "C. diff mechanism", "Flora disrupted → C. diff multiplies → toxins damage colon cells and inflame → colon can't absorb water → watery diarrhea."],
  ["lower", "When to suspect C. diff", "New, unexplained diarrhea, especially ≥3 unformed stools in 24 hours."],
  ["lower", "Hand hygiene for C. diff", "Soap and water. Alcohol sanitizer does not kill the spores."],
  ["lower", "Colonization vs. C. diff infection", "Colonized: carries it with no symptoms. Positive test + symptoms = active infection."],
  ["lower", "Immediate concern in C. diff", "Fluid and electrolyte loss → hypovolemia → ↓kidney perfusion."],
  ["lower", "Severe C. diff complications", "Pseudomembranes, toxic megacolon, perforation, peritonitis, sepsis."],
  ["lower", "Gold-standard C. diff treatment (Pharm connection)", "Oral vancomycin."],
  ["lower", "Appendicitis chain", "Blocked opening → pressure → bacteria → inflammation → ↓blood flow → ischemia → necrosis → perforation."],
  ["lower", "Why does appendicitis pain move to the RLQ?", "Early pain is visceral (poorly localized); it localizes once inflammation reaches the parietal peritoneum."],
  ["lower", "Appendicitis landmark to know", "McBurney's point (RLQ). Obturator, psoas, and Rovsing signs are not tested."],
  ["lower", "Sudden relief of appendicitis pain means…", "Not reassuring: tissue injury may be progressing, including perforation."],
  ["lower", "Diverticulosis vs. diverticulitis", "-osis: pouches present, usually silent. -itis: inflamed pouch, LLQ pain, fever."],
  ["lower", "Diverticular bleeding", "A vessel by a pouch bleeds, even without diverticulitis; usually painless rectal bleeding."],
  ["lower", "Why LLQ pain in diverticulitis?", "Diverticula commonly form in the sigmoid colon (left lower abdomen)."],
  ["lower", "Why avoid colonoscopy in acute diverticulitis?", "Inflamed tissue risks perforation. CT is commonly used instead."],
  ["lower", "Mechanical obstruction vs. ileus", "Mechanical: physical blockage (adhesions, hernia, tumor, stricture). Ileus: no blockage; motility slows or stops."],
  ["lower", "Bowel sounds: mechanical obstruction", "High-pitched early, decreased later."],
  ["lower", "Three causes of ileus", "After surgery, electrolyte disturbances, opioids."],
  ["lower", "How does obstruction cause hypovolemia?", "Fluid trapped in the bowel and bowel wall plus vomiting → less in circulation."],
  ["lower", "IBS in one line", "Gut–brain, motility, and sensitivity problem with no visible tissue damage."],
  ["lower", "IBS + rectal bleeding or weight loss", "Not explained by IBS. Needs further evaluation."],
  ["lower", "Crohn's: two features to know", "Patchy skip lesions anywhere mouth to anus (often terminal ileum and colon) and transmural depth."],
  ["lower", "Why Crohn's causes fistulas and abscesses", "Inflammation goes through the full wall (transmural)."],
  ["lower", "UC: location, distribution, depth", "Colon and rectum only; continuous from the rectum upward; mucosa only."],
  ["lower", "Key UC symptom", "Bloody diarrhea with mucus, plus urgency and tenesmus."],
  ["lower", "Tenesmus", "Persistent feeling of needing to pass stool even when little is left (rectal inflammation)."],
  ["lower", "Which IBD raises colon cancer risk most?", "Long-standing ulcerative colitis."],
  ["lower", "IBD Pharm connection", "Corticosteroids for flares (not long-term); immune-modifying and biologic drugs for maintenance."],
  ["lower", "Colorectal cancer findings that need evaluation", "Unexplained blood in the stool and a persistent change in bowel habits, even in young adults."],
  ["lower", "Frank vs. occult bleeding", "Frank = visible. Occult = not visible, found only by testing."],
  ["lower", "Lower GI bleeding sources", "Diverticular bleeding, colitis (inflamed lining), hemorrhoids, tumors."],
  // Liver & GB
  ["liver", "Five liver functions", "Nutrient metabolism, bile production, bilirubin processing, protein synthesis (albumin, clotting factors), substance processing (drugs, ammonia → urea)."],
  ["liver", "Does the liver make bilirubin?", "No. It processes bilirubin made from normal RBC breakdown."],
  ["liver", "Unconjugated vs. conjugated bilirubin", "Unconjugated: not water-soluble, travels bound to albumin. Conjugated (by the liver, UGT): water-soluble, goes into bile."],
  ["liver", "What gives stool its brown color?", "Stercobilin, made from bilirubin by gut bacteria."],
  ["liver", "Blocked bile duct: urine and stool", "Dark, tea-colored urine (conjugated bilirubin filtered by kidneys) and pale, clay-colored stool (less stercobilin)."],
  ["liver", "Gallstone formation", "More cholesterol than bile can keep dissolved + stasis → crystals → stones. Most are cholesterol."],
  ["liver", "Gallstone risk factors", "Increasing age, rapid weight loss, pregnancy, certain metabolic conditions."],
  ["liver", "Why is gallbladder pain worse after a fatty meal?", "Fat signals the gallbladder to contract; contracting against a blocked outlet raises pressure."],
  ["liver", "Where does gallbladder pain refer?", "Right shoulder or back (shared nerve pathways)."],
  ["liver", "Cystic duct stone and jaundice?", "Usually no jaundice: liver bile still reaches the intestine through the common bile duct."],
  ["liver", "Common bile duct stone findings", "Jaundice, dark urine, pale stool; ↑bilirubin and ↑ALP."],
  ["liver", "First imaging for gallbladder disease", "Ultrasound (stones, thickened wall, fluid around the gallbladder)."],
  ["liver", "Cause of ≈90% of cholecystitis", "A gallstone blocking the cystic duct (calculous)."],
  ["liver", "Acalculous cholecystitis", "Without a stone; mainly in critically ill people."],
  ["liver", "Cholecystitis vs. biliary pain", "Cholecystitis pain is persistent (the wall is inflamed), with fever and ↑WBC/CRP."],
  ["liver", "Bilirubin in uncomplicated cholecystitis", "Often normal. A significant rise suggests a common bile duct obstruction."],
  ["liver", "After cholecystectomy", "Liver still makes bile, but it isn't stored; fatty meals can cause urgent bile-heavy diarrhea → lower-fat diet."],
  ["liver", "Stages of liver failure", "Compensated → decompensated (complications appear) → end stage."],
  ["liver", "Cirrhosis: the two mechanisms", "Loss of normal liver function and portal hypertension."],
  ["liver", "Causes of cirrhosis", "Alcohol-associated liver disease, chronic hepatitis B or C, MASLD, autoimmune, inherited, chronic bile duct disease."],
  ["liver", "Why does cirrhosis cause ascites?", "Portal hypertension pushes fluid out of circulation, and low albumin makes it worse."],
  ["liver", "Why low platelets in cirrhosis?", "Portal hypertension → splenomegaly → spleen holds more platelets."],
  ["liver", "Why confusion in cirrhosis?", "Ammonia isn't converted to urea and reaches the brain → hepatic encephalopathy."],
  ["liver", "Why might AST/ALT be normal in advanced cirrhosis?", "They reflect active cell injury, not function; few working cells are left to release enzymes."],
  ["liver", "Hepatitis A route and course", "Fecal-oral; acute only, never chronic; vaccine exists; supportive care."],
  ["liver", "Hepatitis B routes", "Blood and certain body fluids: sexual, shared injection equipment, needle sticks, perinatal."],
  ["liver", "How long can HBV stay infectious on a surface?", "At least 7 days, even when blood isn't visible."],
  ["liver", "Who is most likely to become chronic with hepatitis B?", "Infants (the younger at infection, the more likely)."],
  ["liver", "HBsAg vs. anti-HBs", "HBsAg (surface antigen) = current infection. Anti-HBs (surface antibody) = immunity from vaccine or recovery."],
  ["liver", "What injures the liver in hepatitis B?", "The immune response against infected liver cells."],
  ["liver", "Hepatitis C chronicity", "More than half become chronic; most associated with long-term chronic liver disease."],
  ["liver", "Positive HCV antibody means…", "Exposure at some point. HCV RNA confirms current infection."],
  ["liver", "Hepatitis C vaccine and cure", "No vaccine; direct-acting antivirals cure most infections."],
  ["liver", "AST/ALT measure…", "Liver cell injury, not function."],
  ["liver", "ALP and GGT measure…", "Bile flow and biliary injury (GGT confirms a high ALP is from liver/biliary, not bone)."],
  ["liver", "Best lab for the liver's ability to make clotting factors", "PT/INR."],
  ["liver", "Low albumin causes…", "Fluid leaks out of vessels (third spacing) → edema, ascites."]
];

